pub const BinaryExpressionVisitorStruct = struct {
    e: *E.Binary,
    level: Level = .lowest,
    flags: ExprFlag.Set = ExprFlag.Set.initEmpty(),
    left_level: Level = .lowest,
    left_flags: ExprFlag.Set = ExprFlag.Set.initEmpty(),
    entry: *const Op = undefined,
    wrap: bool = false,
    right_level: Level = .lowest,

pub fn checkAndPrepare(self: *BinaryExpressionVisitorStruct, p: anytype) bool {
            var e = self.e;
            _ = &e;
            const entry: *const Op = Op.Table.getPtrConst(e.op);
            const e_level = entry.level;
            self.entry = entry;
            self.wrap = (self.level.gte(e_level) or ((e.op == Op.Code.bin_in) and self.flags.contains(.forbid_in)));
            const n = p.writer.written;
            if (((n == p.stmt_start) or (n == p.arrow_expr_start))) {
                switch (e.left.data) {
.e_object => {
self.wrap = true;
},
else => {

},
}
            }
            if (self.wrap) {
                _ = p.print("(");
                _ = self.flags.insert(.forbid_in);
            }
            self.left_level = e_level.sub(1);
            self.right_level = e_level.sub(1);
            const left_level = (&self.left_level);
            const right_level = (&self.right_level);
            if (e.op.isRightAssociative()) {
                left_level.* = e_level;
            }
            if (e.op.isLeftAssociative()) {
                right_level.* = e_level;
            }
            switch (e.op) {
.bin_nullish_coalescing => {
switch (e.left.data) {
.e_binary => {
const left = e.left.data.e_binary;
            switch (left.op) {
.bin_logical_and, .bin_logical_or => {
left_level.* = .prefix;
},
else => {

},
}
},
else => {

},
}
            switch (e.right.data) {
.e_binary => {
const right = e.right.data.e_binary;
            switch (right.op) {
.bin_logical_and, .bin_logical_or => {
right_level.* = .prefix;
},
else => {

},
}
},
else => {

},
}
},
.bin_pow => {
switch (e.left.data) {
.e_unary => {
const left = e.left.data.e_unary;
            if ((left.op.unaryAssignTarget() == .none)) {
                left_level.* = .call;
            }
},
.e_await, .e_undefined, .e_number => {
left_level.* = .call;
},
.e_boolean, .e_branch_boolean => {
if (p.options.minify_syntax) {
                left_level.* = .call;
            }
},
else => {

},
}
},
else => {

},
}
            if (((e.left.data == .e_private_identifier) and (e.op == .bin_in))) {
                const priv_id = e.left.data.e_private_identifier;
                const name = p.renamer.nameForSymbol(priv_id.ref);
                _ = p.addSourceMappingForName(e.left.loc, name, priv_id.ref);
                _ = p.printIdentifier(name);
                _ = self.visitRightAndFinish(p);
                return false;
            }
            self.left_flags = .{};
            if (self.flags.contains(.forbid_in)) {
                _ = self.left_flags.insert(.forbid_in);
            }
            if ((e.op == .bin_comma)) {
                _ = self.left_flags.insert(.expr_result_is_unused);
            }
            return true;
    }

pub fn visitRightAndFinish(self: *BinaryExpressionVisitorStruct, p: anytype) void {
            const e = self.e;
            const entry = self.entry;
            var flags = ExprFlag.Set;
            _ = &flags;
            if ((e.op != .bin_comma)) {
                _ = p.printSpace();
            }
            if (entry.is_keyword) {
                _ = p.printSpaceBeforeIdentifier();
                _ = p.print(entry.text);
            } else {
                _ = p.printSpaceBeforeOperator(e.op);
                _ = p.print(entry.text);
                p.prev_op = e.op;
                p.prev_op_end = p.writer.written;
            }
            _ = p.printSpace();
            if (((e.op == .bin_comma) and self.flags.contains(.expr_result_is_unused))) {
                _ = flags.insert(.expr_result_is_unused);
            }
            if (self.flags.contains(.forbid_in)) {
                _ = flags.insert(.forbid_in);
            }
            _ = p.printExpr(e.right, self.right_level, flags);
            if (self.wrap) {
                _ = p.print(")");
            }
    }
};

