    append_newline: bool = false,
    approximate_newline_count: usize = 0,
    last_bytes: [2]u8 = .{ 0, 0 },

pub fn getMutableBuffer(self: *BufferWriter) *MutableString {
            return (&self.buffer);
    }

pub fn takeBuffer(self: *BufferWriter) MutableString {
            defer {
            self.buffer = .initEmpty(self.buffer.allocator);
            }
            return self.buffer;
    }

pub fn getWritten(self: *BufferWriter) []u8 {
            return self.buffer.list.items;
    }

pub fn init(allocator: std.mem.Allocator) BufferWriter {
            return BufferWriter{ .buffer = MutableString.initEmpty(allocator) };
    }

pub fn print(ctx: *BufferWriter, comptime fmt: []const u8, args: anytype) !void {
            _ = try ctx.buffer.list.writer(ctx.buffer.allocator).print(fmt, args);
    }

pub fn writeByteNTimes(ctx: *BufferWriter, byte: u8, n: usize) !void {
