    }

pub fn writeByte(ctx: *BufferWriter, byte: u8) !usize {
            _ = try ctx.buffer.appendChar(byte);
            ctx.approximate_newline_count = (ctx.approximate_newline_count + @intFromBool((byte == 10)));
            ctx.last_bytes = .{ ctx.last_bytes[1], byte };
            return 1;
    }

pub fn writeAll(ctx: *BufferWriter, bytes: anytype) !usize {
            _ = try ctx.buffer.append(bytes);
            ctx.approximate_newline_count = (ctx.approximate_newline_count + @intFromBool(((bytes.len > 0) and (bytes[@as(usize, @intCast((bytes.len - 1)))] == 10))));
            if ((bytes.len >= 2)) {
                ctx.last_bytes = (bytes[(bytes.len - 2)..][0..2]).*;
            } else {
                if ((bytes.len >= 1)) {
                    ctx.last_bytes = .{ ctx.last_bytes[1], bytes[@as(usize, @intCast((bytes.len - 1)))] };
                }
            }
            return bytes.len;
    }

pub fn slice(self: *BufferWriter) []const u8 {
            return self.buffer.list.items;
    }

pub fn getLastByte(ctx: *const BufferWriter) u8 {
            return ctx.last_bytes[1];
    }

pub fn getLastLastByte(ctx: *const BufferWriter) u8 {
            return ctx.last_bytes[0];
    }

pub fn reserveNext(ctx: *BufferWriter, count: u64) anyerror![*]u8 {
            _ = try ctx.buffer.growIfNeeded(count);
            return (blk: {
            break :blk @as([*]u8, @ptrCast(@alignCast(&(ctx.buffer.list.items.ptr[@as(usize, @intCast(ctx.buffer.list.items.len))]))));

});
    }

pub fn advanceBy(ctx: *BufferWriter, count: u64) void {
            if (comptime Environment.isDebug) {
