pub fn printSymbol(p: *Printer, sym_ref: Ref) void {
            _ = bun.assert((!sym_ref.isNull()));
            const name = p.renamer.nameForSymbol(sym_ref);
            _ = p.printIdentifier(name);
    }

pub fn printClauseAlias(p: *Printer, alias: []const u8) void {
            _ = bun.assert((alias.len > 0));
            if ((!strings.containsNonBmpCodePointOrIsInvalidIdentifier(alias))) {
                _ = p.printSpaceBeforeIdentifier();
                _ = p.printIdentifier(alias);
            } else {
