pub fn printFnArgs(p: *Printer, open_paren_loc: ?logger.Loc, args: []G.Arg, has_rest_arg: bool, _: bool) void {
            const wrap = true;
            if (wrap) {
                if (open_paren_loc) |loc| {
                    _ = &loc;
                    _ = p.addSourceMapping(loc);
                }
                _ = p.print("(");
            }
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(args)) |arg| {
                _ = &arg;
                defer {
                i = (i + 1);
                }
                if ((i != 0)) {
                    _ = p.print(",");
                    _ = p.printSpace();
                }
                if ((has_rest_arg and ((i + 1) == args.len))) {
                    _ = p.print("..");
                }
                _ = p.printBinding(arg.binding, .{});
                if (arg.default) |default| {
                    _ = &default;
                    _ = p.printWhitespacer(ws(" = "));
                    _ = p.printExpr(default, .comma, ExprFlag.Set.initEmpty());
                }
            }
            if (wrap) {
                _ = p.print(")");
            }
    }

pub fn printFunc(p: *Printer, func: G.Fn) void {
            _ = p.printFnArgs(func.open_parens_loc, func.args, func.flags.contains(.has_rest_arg), false);
            _ = p.printSpace();
            _ = p.printBlock(func.body.loc, func.body.stmts, null, TopLevel.init(.no));
    }

pub fn printClass(p: *Printer, cls: G.Class) void {
            if (cls.extends) |ext| {
                _ = &ext;
                _ = p.print(" ext");
                _ = p.printSpace();
                _ = p.printExpr(ext, Level.new.sub(1), ExprFlag.Set.initEmpty());
            }
            _ = p.printSpace();
            _ = p.addSourceMapping(cls.body_loc);
            _ = p.print("{");
            _ = p.printNewline();
            _ = p.indent();
            for (cp_iter_slice(cls.properties)) |item| {
                _ = &item;
                _ = p.printSemicolonIfNeeded();
                _ = p.printIndent();
                if ((item.kind == .class_static_block)) {
                    _ = p.print("static");
                    _ = p.printSpace();
                    _ = p.printBlock(item.class_static_block.?.loc, item.class_static_block.?.stmts.slice(), null, TopLevel.init(.no));
                    _ = p.printNewline();
                    continue;
                }
                _ = p.printProperty(item);
                if (((if (@typeInfo(@TypeOf(item)) == .@"enum") @intFromEnum(item) else item.value) == null)) {
                    _ = p.printSemicolonAfterStatement();
                } else {
                    _ = p.printNewline();
                }
            }
            p.needs_semicolon = false;
            _ = p.unindent();
            _ = p.printIndent();
            if ((cls.close_brace_loc.start > cls.body_loc.start)) {
                _ = p.addSourceMapping(cls.close_brace_loc);
            }
            _ = p.print("}");
    }

