pub fn printStringCharactersUTF8(e: *Printer, text: []const u8, quote: u8) void {
            const writer = e.writer.stdWriter();
            _ = (((switch (quote) {
'\'' => writePreQuotedString(text, @TypeOf(writer), writer, 39, ascii_only, false, .utf8),
'"' => writePreQuotedString(text, @TypeOf(writer), writer, 34, ascii_only, false, .utf8),
'`' => writePreQuotedString(text, @TypeOf(writer), writer, 96, ascii_only, false, .utf8),
else => unreachable,
})) catch unreachable);
    }

