pub fn isUnboundEvalIdentifier(p: *Printer, value: Expr) bool {
            switch (value.data) {
.e_identifier => |ident| {
if (ident.ref.isSourceContentsSlice()) {
                return false;
            }
            const sym_opt = p.symbols().get(p.symbols().follow(ident.ref));
            if ((sym_opt == null)) {
                return false;
            }
            const symbol = sym_opt.?;
            return ((symbol.kind == .unbound) and strings.eqlComptime(symbol.original_name, "eval"));
},
else => {
return false;
},
}
    }

pub fn symbols(p: *Printer) js_ast.Symbol.Map {
            return p.renamer.symbols();
    }

pub fn printRequireError(p: *Printer, text: []const u8) void {
            _ = p.print("(()=>{throw new Error(\"Cannot require module \"+");
            _ = p.printStringLiteralUTF8(text, false);
            _ = p.print(");})()");
