pub fn importRecord(p: *const Printer, import_record_index: usize) *const ImportRecord {
            return (&p.import_records[@as(usize, @intCast(import_record_index))]);
    }

pub fn isUnboundIdentifier(p: *Printer, expr: *const Expr) bool {
            if ((expr.data != .e_identifier)) {
                return false;
            }
            const sym_ref = expr.data.e_identifier.ref;
            const sym_opt = p.symbols().get(p.symbols().follow(sym_ref));
            if ((sym_opt == null)) {
                return false;
            }
            const symbol = sym_opt.?;
            return (symbol.kind == .unbound);
    }

pub fn printRequireOrImportExpr(p: *Printer, import_record_index: u32, was_unwrapped_require: bool, leading_interior_comments: []G.Comment, import_options: Expr, level_: Level, flags: ExprFlag.Set) void {
            _ = &leading_interior_comments;
            var level = level_;
            _ = &level;
            const wrap = (level.gte(.@"new") or flags.contains(.forbid_call));
            if (wrap) {
                _ = p.print("(");
            }
            defer {
            if (wrap) {
                _ = p.print(")");
            }
            }
            _ = assert((p.import_records.len > import_record_index));
            const record = p.importRecord(import_record_index);
            const module_type = p.options.module_type;
            if (comptime is_bun_platform) {
                switch (record.tag) {
.bun => {
if ((record.kind == .dynamic)) {
                    _ = p.print("Promise.resolve(globalThis.Bun)");
                    return;
                } else {
                    if (((record.kind == .require) or (record.kind == .stmt))) {
                        _ = p.print("globalThis.Bun");
                        return;
                    }
                }
},
else => {

},
}
            }
            if (record.source_index.isValid()) {
                var req_meta = p.options.requireOrImportMetaForSource(record.source_index.get(), was_unwrapped_require);
                _ = &req_meta;
                if (flags.contains(.expr_result_is_unused)) {
                    req_meta.exports_ref = Ref.None;
                }
                if (((record.kind == .dynamic) and req_meta.is_wrapper_async)) {
                    _ = p.printSpaceBeforeIdentifier();
                    _ = p.printSymbol(req_meta.wrapper_ref);
                    _ = p.print("()");
                    if (req_meta.exports_ref.isValid()) {
                        _ = p.printDotThenPrefix();
                        _ = p.printSpaceBeforeIdentifier();
                        _ = p.printSymbol(req_meta.exports_ref);
                        _ = p.printDotThenSuffix();
                    }
                    return;
                }
                const has_side_effects = (((req_meta.wrapper_ref.isValid() or req_meta.exports_ref.isValid()) or req_meta.was_unwrapped_require) or (p.options.input_files_for_dev_server != null));
                if ((record.kind == .dynamic)) {
                    _ = p.printSpaceBeforeIdentifier();
                    _ = p.print("Promise.resolve()");
                    if (has_side_effects) {
                        level = p.printDotThenPrefix();
                    }
                }
                defer {
                if (((record.kind == .dynamic) and has_side_effects)) {
                    _ = p.printDotThenSuffix();
                }
                }
                const wrap_comma_operator = ((req_meta.exports_ref.isValid() and req_meta.wrapper_ref.isValid()) and level.gte(.comma));
                if (wrap_comma_operator) {
                    _ = p.print("(");
                }
                defer {
                if (wrap_comma_operator) {
                    _ = p.print(")");
                }
                }
                const wrap_with_to_esm = record.flags.wrap_with_to_esm;
                if (wrap_with_to_esm) {
                    _ = p.printSpaceBeforeIdentifier();
                    _ = p.printSymbol(p.options.to_esm_ref);
                    _ = p.print("(");
                }
                if (p.options.input_files_for_dev_server) |input_files| {
                    _ = &input_files;
                    _ = bun.assert((module_type == .internal_bake_dev));
                    _ = p.printSpaceBeforeIdentifier();
                    _ = p.printSymbol(p.options.hmr_ref);
                    _ = p.print(".require(");
                    const path = input_files[@as(usize, @intCast(record.source_index.get()))].path;
                    _ = p.printStringLiteralUTF8(path.pretty, false);
                    _ = p.print(")");
                } else {
                    if ((!req_meta.was_unwrapped_require)) {
                        if (req_meta.wrapper_ref.isValid()) {
                            _ = p.printSpaceBeforeIdentifier();
                            _ = p.printSymbol(req_meta.wrapper_ref);
                            _ = p.print("()");
                            if (req_meta.exports_ref.isValid()) {
                                _ = p.print(",");
                                _ = p.printSpace();
                            }
                        }
                        if (req_meta.exports_ref.isValid()) {
                            const wrap_with_to_cjs = record.flags.wrap_with_to_commonjs;
                            if (wrap_with_to_cjs) {
                                _ = p.printSymbol(p.options.to_commonjs_ref);
                                _ = p.print("(");
                            }
                            _ = p.printSymbol(req_meta.exports_ref);
                            if (wrap_with_to_cjs) {
                                _ = p.print(")");
                            }
                        }
                    } else {
                        if ((!req_meta.exports_ref.isNull())) {
                            _ = p.printSymbol(req_meta.exports_ref);
                        }
                    }
                }
                if (wrap_with_to_esm) {
                    if ((p.options.input_module_type == .esm)) {
                        _ = p.print(",");
                        _ = p.printSpace();
                        _ = p.print("1");
                    }
                    _ = p.print(")");
                }
                return;
            }
            if ((record.kind != .dynamic)) {
                _ = p.printSpaceBeforeIdentifier();
                if (p.options.inline_require_and_import_errors) {
                    if ((record.path.is_disabled and record.flags.handles_import_errors)) {
                        _ = p.printRequireError(record.path.text);
                        return;
                    }
                    if (record.path.is_disabled) {
                        _ = p.printDisabledImport();
                        return;
                    }
                }
                const wrap_with_to_esm = record.flags.wrap_with_to_esm;
                if ((module_type == .internal_bake_dev)) {
                    _ = p.printSpaceBeforeIdentifier();
                    _ = p.printSymbol(p.options.hmr_ref);
                    if ((record.tag == .builtin)) {
                        _ = p.print(".builtin(");
                    } else {
                        _ = p.print(".require(");
                    }
                    const path = record.path;
                    _ = p.printStringLiteralUTF8(path.pretty, false);
                    _ = p.print(")");
                    return;
                } else {
                    if (wrap_with_to_esm) {
                        _ = p.printSpaceBeforeIdentifier();
                        _ = p.printSymbol(p.options.to_esm_ref);
                        _ = p.print("(");
                    }
