                    var fetch_parameters: analyze_transpiled_module.ModuleInfo.FetchParameters = .none;
                    _ = &fetch_parameters;
                    if (comptime is_bun_platform) {
                        if (record.loader) |loader| {
                            _ = &loader;
                            fetch_parameters = (switch (loader) {
.json => .json,
.jsx => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("jsx"))),
.js => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("js"))),
.ts => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("ts"))),
.tsx => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("tsx"))),
.css => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("css"))),
.file => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("file"))),
.jsonc => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("jsonc"))),
.toml => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("toml"))),
.yaml => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("yaml"))),
.wasm => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("wasm"))),
.napi => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("napi"))),
.base64 => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("base64"))),
.dataurl => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("dataurl"))),
.text => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("text"))),
.bunsh => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("sh"))),
.sqlite, .sqlite_embedded => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("sqlite"))),
.html => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("html"))),
.json5 => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("json5"))),
.md => analyze_transpiled_module.ModuleInfo.FetchParameters.hostDefined(bun.handleOom(mi.str("md"))),
});
                        }
                    }
                    _ = bun.handleOom(mi.requestModule(irp_id, fetch_parameters));
                    if (s.default_name) |name| {
                        _ = &name;
                        const local_name = p.renamer.nameForSymbol(name.ref.?);
                        const local_name_id = bun.handleOom(mi.str(local_name));
                        _ = bun.handleOom(mi.addVar(local_name_id, .lexical));
                        _ = bun.handleOom(mi.addImportInfoSingle(irp_id, bun.handleOom(mi.str("default")), local_name_id, false));
                    }
                    for (s.items) |item| {
                        _ = &item;
                        const local_name = p.renamer.nameForSymbol((if (@typeInfo(@TypeOf(item)) == .@"enum" or @typeInfo(@TypeOf(item)) == .@"union") @tagName(item) else item.name).ref.?);
                        const local_name_id = bun.handleOom(mi.str(local_name));
                        _ = bun.handleOom(mi.addVar(local_name_id, .lexical));
                        _ = bun.handleOom(mi.addImportInfoSingle(irp_id, bun.handleOom(mi.str(item.alias)), local_name_id, false));
                    }
                    if (record.flags.contains_import_star) {
                        const local_name = p.renamer.nameForSymbol(s.namespace_ref);
                        _ = bun.handleOom(mi.addVar(bun.handleOom(mi.str(local_name)), .lexical));
                        _ = bun.handleOom(mi.addImportInfoNamespace(irp_id, bun.handleOom(mi.str(local_name))));
                    }
                }
            }
},
.s_block => |s| {
_ = p.printIndent();
            _ = p.printBlock(stmt.loc, s.stmts, s.close_brace_loc, tlmtlo.subVar());
            _ = p.printNewline();
},
.s_debugger => {
_ = p.printIndent();
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(stmt.loc);
            _ = p.print("debugger");
            _ = p.printSemicolonAfterStatement();
},
.s_directive => |s| {
if (comptime is_json) {
                _ = unreachable;
            }
            _ = p.printIndent();
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(stmt.loc);
            _ = p.printStringLiteralUTF8((if (@typeInfo(@TypeOf(s)) == .@"enum") @intFromEnum(s) else s.value), false);
            _ = p.printSemicolonAfterStatement();
},
.s_break => |s| {
_ = p.printIndent();
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(stmt.loc);
            _ = p.print("break");
            if (s.label) |label| {
                _ = &label;
                _ = p.print(" ");
                _ = p.printSymbol(label.ref.?);
            }
            _ = p.printSemicolonAfterStatement();
},
.s_continue => |s| {
_ = p.printIndent();
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(stmt.loc);
            _ = p.print("continue");
            if (s.label) |label| {
                _ = &label;
                _ = p.print(" ");
                _ = p.printSymbol(label.ref.?);
            }
            _ = p.printSemicolonAfterStatement();
},
.s_return => |s| {
_ = p.printIndent();
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(stmt.loc);
            _ = p.print("return");
            if ((if (@typeInfo(@TypeOf(s)) == .@"enum") @intFromEnum(s) else s.value)) |value| {
                _ = &value;
                _ = p.printSpace();
                _ = p.printExpr(value, .lowest, ExprFlag.Set.initEmpty());
            }
            _ = p.printSemicolonAfterStatement();
},
.s_throw => |s| {
_ = p.printIndent();
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(stmt.loc);
            _ = p.print("throw");
            _ = p.printSpace();
            _ = p.printExpr((if (@typeInfo(@TypeOf(s)) == .@"enum") @intFromEnum(s) else s.value), .lowest, ExprFlag.Set.initEmpty());
            _ = p.printSemicolonAfterStatement();
},
.s_expr => |s| {
if (((!p.options.minify_whitespace) and (p.options.indent.count > 0))) {
                _ = p.printIndent();
            }
            p.stmt_start = p.writer.written;
            const result_unused = ExprFlag.ExprResultIsUnused;
            _ = p.printExpr((if (@typeInfo(@TypeOf(s)) == .@"enum") @intFromEnum(s) else s.value), .lowest, result_unused());
            _ = p.printSemicolonAfterStatement();
},
else => |tag| {
_ = Output.panic("Unexpected tag in printStmt: .{s}", .{ @tagName(tag) });
},
}
    }

pub fn printModuleExportSymbol(p: *Printer) void {
            _ = p.print("module.exports");
    }

pub fn printImportRecordPath(p: *Printer, import_record: *const ImportRecord) void {
            if (comptime is_json) {
                _ = unreachable;
            }
            const quote = bestQuoteCharForString(u8, import_record.path.text, false);
            if ((import_record.flags.print_namespace_in_path and (!import_record.path.isFile()))) {
                _ = p.print(quote);
                _ = p.printStringCharactersUTF8(import_record.path.namespace, quote);
                _ = p.print(":");
                _ = p.printStringCharactersUTF8(import_record.path.text, quote);
                _ = p.print(quote);
            } else {
                _ = p.print(quote);
                _ = p.printStringCharactersUTF8(import_record.path.text, quote);
                _ = p.print(quote);
            }
    }

pub fn printBundledImport(p: *Printer, record: ImportRecord, s: *S.Import) void {
            if (record.flags.is_internal) {
                return;
            }
            const import_record = p.importRecord(s.import_record_index);
            const is_disabled = import_record.path.is_disabled;
            const module_id = import_record.module_id;
            if (record.path.is_disabled) {
                if ((p.symbols().get(s.namespace_ref) == null)) {
                    return;
                }
            }
            switch (ImportVariant.determine((&record), s)) {
.path_only => {
if ((!is_disabled)) {
                _ = p.printCallModuleID(module_id);
                _ = p.printSemicolonAfterStatement();
            }
},
.import_items_and_default, .import_default => {
if ((!is_disabled)) {
                _ = p.print("var $");
                _ = p.printModuleId(module_id);
                _ = p.@"print = "();
                _ = p.printLoadFromBundle(s.import_record_index);
                if (s.default_name) |default_name| {
                    _ = &default_name;
                    _ = p.print(", ");
                    _ = p.printSymbol(default_name.ref.?);
                    _ = p.print(" = (($");
                    _ = p.printModuleId(module_id);
                    _ = p.print(" && \"default\" in $");
                    _ = p.printModuleId(module_id);
                    _ = p.print(") ? $");
                    _ = p.printModuleId(module_id);
                    _ = p.print(".default : $");
                    _ = p.printModuleId(module_id);
                    _ = p.print(")");
                }
            } else {
                if (s.default_name) |default_name| {
                    _ = &default_name;
                    _ = p.print("var ");
                    _ = p.printSymbol(default_name.ref.?);
                    _ = p.@"print = "();
                    _ = p.printDisabledImport();
                }
            }
            _ = p.printSemicolonAfterStatement();
},
.import_star_and_import_default => {
_ = p.print("var ");
            _ = p.printSymbol(s.namespace_ref);
            _ = p.@"print = "();
            _ = p.printLoadFromBundle(s.import_record_index);
            if (s.default_name) |default_name| {
                _ = &default_name;
                _ = p.print(",");
                _ = p.printSpace();
                _ = p.printSymbol(default_name.ref.?);
                _ = p.@"print = "();
                if ((!is_bun_platform)) {
                    _ = p.print("(");
                    _ = p.printSymbol(s.namespace_ref);
                    _ = p.printWhitespacer(ws(" && \"default\" in "));
                    _ = p.printSymbol(s.namespace_ref);
                    _ = p.printWhitespacer(ws(" ? "));
                    _ = p.printSymbol(s.namespace_ref);
                    _ = p.printWhitespacer(ws(".default : "));
                    _ = p.printSymbol(s.namespace_ref);
                    _ = p.print(")");
                } else {
                    _ = p.printSymbol(s.namespace_ref);
                }
            }
            _ = p.printSemicolonAfterStatement();
},
.import_star => {
_ = p.print("var ");
            _ = p.printSymbol(s.namespace_ref);
            _ = p.@"print = "();
            _ = p.printLoadFromBundle(s.import_record_index);
            _ = p.printSemicolonAfterStatement();
},
else => {
_ = p.print("var $");
            _ = p.printModuleIdAssumeEnabled(module_id);
            _ = p.@"print = "();
            _ = p.printLoadFromBundle(s.import_record_index);
            _ = p.printSemicolonAfterStatement();
},
}
    }

pub fn printLoadFromBundle(p: *Printer, import_record_index: u32) void {
            _ = p.printLoadFromBundleWithoutCall(import_record_index);
            _ = p.print("()");
    }

pub fn printDisabledImport(p: *Printer) void {
            _ = p.printWhitespacer(ws("(() => ({}))"));
    }

pub fn printLoadFromBundleWithoutCall(p: *Printer, import_record_index: u32) void {
            const record = p.importRecord(import_record_index);
            if (record.path.is_disabled) {
                _ = p.printDisabledImport();
                return;
            }
            _ = @call(bun.callmod_inline, printModuleId, .{ p, p.importRecord(import_record_index).module_id });
    }

pub fn printCallModuleID(p: *Printer, module_id: u32) void {
            _ = printModuleId(p, module_id);
            _ = p.print("()");
    }

pub fn printModuleId(p: *Printer, module_id: u32) void {
            _ = bun.assert((module_id != 0));
            _ = p.printModuleIdAssumeEnabled(module_id);
    }

pub fn printModuleIdAssumeEnabled(p: *Printer, module_id: u32) void {
            _ = p.print("$");
            _ = ((std.fmt.formatInt(module_id, 16, .lower, .{}, p)) catch unreachable);
    }

pub fn printBundledRexport(p: *Printer, name: []const u8, import_record_index: u32) void {
            _ = p.print("Object.defineProperty(");
            _ = p.printModuleExportSymbol();
            _ = p.print(",");
            _ = p.printStringLiteralUTF8(name, true);
            _ = p.printWhitespacer(ws(",{get: () => ("));
            _ = p.printLoadFromBundle(import_record_index);
            _ = p.printWhitespacer(ws("), enumerable: true, configurable: true})"));
    }

pub fn printBundledExport(p: *Printer, name: []const u8, identifier: []const u8) void {
            _ = p.print("Object.defineProperty(");
            _ = p.printModuleExportSymbol();
            _ = p.print(",");
            _ = p.printStringLiteralUTF8(name, true);
            _ = p.print(",{get: () => ");
            _ = p.printIdentifier(identifier);
            _ = p.print(", enumerable: true, configurable: true})");
