pub fn printForLoopInit(p: *Printer, initSt: Stmt) void {
            switch (initSt.data) {
.s_expr => |s| {
_ = p.printExpr((if (@typeInfo(@TypeOf(s)) == .@"enum") @intFromEnum(s) else s.value), .lowest, ExprFlag.Set.init(.{ .forbid_in = true, .expr_result_is_unused = true }));
},
.s_local => |s| {
switch (s.kind) {
.k_var => {
_ = p.printDecls("var", s.decls.slice(), ExprFlag.Set.init(.{ .forbid_in = true }), .{});
},
.k_let => {
_ = p.printDecls("let", s.decls.slice(), ExprFlag.Set.init(.{ .forbid_in = true }), .{});
},
.k_const => {
_ = p.printDecls("const", s.decls.slice(), ExprFlag.Set.init(.{ .forbid_in = true }), .{});
},
.k_using => {
_ = p.printDecls("using", s.decls.slice(), ExprFlag.Set.init(.{ .forbid_in = true }), .{});
},
.k_await_using => {
_ = p.printDecls("await using", s.decls.slice(), ExprFlag.Set.init(.{ .forbid_in = true }), .{});
},
}
},
.s_empty => {

},
else => {
_ = Output.panic("Internal error: Unexpected stmt in for loop", .{});
},
}
    }

pub fn printIf(p: *Printer, s: *const S.If, loc: logger.Loc, tlmtlo: TopLevel) void {
            _ = p.printSpaceBeforeIdentifier();
            _ = p.addSourceMapping(loc);
            _ = p.print("if");
            _ = p.printSpace();
            _ = p.print("(");
            _ = p.printExpr(s.test_, .lowest, ExprFlag.Set.initEmpty());
            _ = p.print(")");
            switch (s.yes.data) {
.s_block => |block| {
_ = p.printSpace();
            _ = p.printBlock(s.yes.loc, block.stmts, block.close_brace_loc, tlmtlo);
            if ((s.no != null)) {
                _ = p.printSpace();
            } else {
                _ = p.printNewline();
            }
},
else => {
if (wrapToAvoidAmbiguousElse((&s.yes.data))) {
                _ = p.printSpace();
                _ = p.print("{");
                _ = p.printNewline();
                _ = p.indent();
                _ = ((p.printStmt(s.yes, tlmtlo)) catch unreachable);
                _ = p.unindent();
                p.needs_semicolon = false;
                _ = p.printIndent();
                _ = p.print("}");
                if ((s.no != null)) {
                    _ = p.printSpace();
                } else {
                    _ = p.printNewline();
                }
            } else {
                _ = p.printNewline();
                _ = p.indent();
                _ = ((p.printStmt(s.yes, tlmtlo)) catch unreachable);
                _ = p.unindent();
                if ((s.no != null)) {
                    _ = p.printIndent();
                }
            }
},
}
            if (s.no) |no_block| {
                _ = &no_block;
                _ = p.printSemicolonIfNeeded();
                _ = p.printSpaceBeforeIdentifier();
                _ = p.addSourceMapping(no_block.loc);
                _ = p.print("else");
                switch (no_block.data) {
.s_block => {
_ = p.printSpace();
                _ = p.printBlock(no_block.loc, no_block.data.s_block.stmts, null, tlmtlo);
                _ = p.printNewline();
},
.s_if => {
_ = p.printIf(no_block.data.s_if, no_block.loc, tlmtlo);
},
else => {
_ = p.printNewline();
                _ = p.indent();
                _ = ((p.printStmt(no_block, tlmtlo)) catch unreachable);
                _ = p.unindent();
},
}
            }
    }

pub fn wrapToAvoidAmbiguousElse(s_: *const Stmt.Data) bool {
            var s = s_;
            _ = &s;
            while (true) {
                switch (s.*) {
.s_if => |index| {
if (index.no) |*no| {
                    _ = &no;
                    s = (&(no.*).data);
                } else {
                    return true;
                }
},
.s_for => |current| {
s = (&current.body.data);
},
.s_for_in => |current| {
s = (&current.body.data);
},
.s_for_of => |current| {
s = (&current.body.data);
},
.s_while => |current| {
s = (&current.body.data);
},
.s_with => |current| {
s = (&current.body.data);
},
.s_label => |current| {
s = (&current.stmt.data);
},
else => {
return false;
},
}
            }
    }

pub fn tryToGetImportedEnumValue(p: *Printer, target: Expr, name: []const u8) ?js_ast.InlinedEnumValue.Decoded {
            if (target.data.@"as"(.e_import_identifier)) |id| {
                _ = &id;
                const sym_ref = p.symbols().follow(id.ref);
                if (p.symbols().get(sym_ref)) |symbol| {
                    _ = &symbol;
                    if ((symbol.kind == .ts_enum)) {
                        if (p.options.ts_enums.get(sym_ref)) |enum_value| {
                            _ = &enum_value;
                            if (enum_value.get(name)) |value| {
                                _ = &value;
                                return value.decode();
                            }
                        }
                    }
                }
            }
            return null;
    }

pub fn printInlinedEnum(p: *Printer, inlined: js_ast.InlinedEnumValue.Decoded, comment: []const u8, level: Level) void {
            switch (inlined) {
.number => |num| {
_ = p.printNumber(num, level);
},
.string => |str| {
_ = p.printExpr(.{ .data = .{ .e_string = str }, .loc = logger.Loc.Empty }, level, .{});
},
}
            if (((!p.options.minify_whitespace) and (!p.options.minify_identifiers))) {
                if ((!bun.strings.containsComptime(comment, "*/"))) {
                    _ = p.print(" /* ");
                    _ = p.print(comment);
                    _ = p.print(" */");
                }
            }
    }

pub fn printDeclStmt(p: *Printer, is_export: bool, comptime keyword: []const u8, decls: []G.Decl, tlmtlo: TopLevel) void {
            if (((!rewrite_esm_to_cjs) and is_export)) {
                _ = p.print("export ");
            }
            const tlm: TopLevelAndIsExport = (if (may_have_module_info) TopLevelAndIsExport{ .is_export = is_export, .is_top_level = (if (comptime strings.eqlComptime(keyword, "var")) (if (tlmtlo.isTopLevel()) .declared else null) else (if ((tlmtlo.is_top_level == .yes)) .lexical else null)) } else ({
}));
            _ = p.printDecls(keyword, decls, ExprFlag.Set.initEmpty(), tlm);
            _ = p.printSemicolonAfterStatement();
            if (((rewrite_esm_to_cjs and is_export) and (decls.len > 0))) {
                for (cp_iter_slice(decls)) |decl| {
                    _ = &decl;
                    _ = p.printIndent();
                    _ = p.printSymbol(p.options.runtime_imports.__export.?.ref);
                    _ = p.print("(");
                    _ = p.printSpaceBeforeIdentifier();
                    _ = p.printModuleExportSymbol();
                    _ = p.print(",");
                    _ = p.printSpace();
                    switch (decl.binding.data) {
.b_identifier => |ident| {
_ = p.print("{");
                    _ = p.printSpace();
                    _ = p.printSymbol(ident.ref);
                    if (p.options.minify_whitespace) {
                        _ = p.print(":()=>(");
                    } else {
                        _ = p.print(": () => (");
                    }
                    _ = p.printSymbol(ident.ref);
                    _ = p.print(") }");
},
.b_object => |obj| {
_ = p.print("{");
                    _ = p.printSpace();
                    for (cp_iter_slice(obj.properties)) |prop| {
                        _ = &prop;
                        switch ((if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value).data) {
.b_identifier => |ident| {
_ = p.printSymbol(ident.ref);
                        if (p.options.minify_whitespace) {
                            _ = p.print(":()=>(");
                        } else {
                            _ = p.print(": () => (");
                        }
                        _ = p.printSymbol(ident.ref);
                        _ = p.print("),");
                        _ = p.printNewline();
},
else => {

},
}
                    }
                    _ = p.print("}");
},
else => {
_ = p.printBinding(decl.binding, .{});
},
}
                    _ = p.print(")");
                    _ = p.printSemicolonAfterStatement();
                }
            }
    }

pub fn printIdentifier(p: *Printer, identifier: []const u8) void {
            if (comptime ascii_only) {
                _ = p.printIdentifierAsciiOnly(identifier);
            } else {
                _ = p.print(identifier);
            }
    }

pub fn printIdentifierAsciiOnly(p: *Printer, identifier: []const u8) void {
            var ascii_start: usize = 0;
            _ = &ascii_start;
            var is_ascii = false;
            _ = &is_ascii;
            var iter = CodepointIterator.init(identifier);
            _ = &iter;
            var cursor: CodepointIterator.Cursor = .{};
            _ = &cursor;
            while (iter.next((&cursor))) {
                switch (cursor.c) {
first_ascii...last_ascii => {
if ((!is_ascii)) {
                    ascii_start = cursor.i;
                    is_ascii = true;
                }
},
else => {
if (is_ascii) {
                    _ = p.print(identifier[ascii_start..cursor.i]);
                    is_ascii = false;
                }
                _ = p.print("\\u{");
                _ = ((p.fmt("{x}", .{ cursor.c })) catch unreachable);
                _ = p.print("}");
},
}
            }
            if (is_ascii) {
                _ = p.print(identifier[ascii_start..]);
            }
    }

pub fn printIdentifierUTF16(p: *Printer, name: []const u16) !void {
            const n = name.len;
            var i: usize = 0;
            _ = &i;
            while ((i < n)) {
                var c: u32 = (if (comptime @typeInfo(@TypeOf(name[@as(usize, @intCast(i))])) == .@"enum") cp_cast_int(u32, @intFromEnum(name[@as(usize, @intCast(i))])) else cp_cast_int(u32, name[@as(usize, @intCast(i))]));
                _ = &c;
                i = (i + 1);
                if ((((c & (~(if (comptime @typeInfo(@TypeOf(1023)) == .@"enum") cp_cast_int(u32, @intFromEnum(1023)) else cp_cast_int(u32, 1023)))) == 55296) and (i < n))) {
                    c = (65536 + (cp_shl((c & 1023), 10) | (name[@as(usize, @intCast(i))] & 1023)));
                    i = (i + 1);
                }
                if (((comptime ascii_only) and (c > last_ascii))) {
